// Package messages defines the messages that the gRPC example exchanges.
//
// They are plain Go structs with the pb tags, so neither a .proto file nor a
// generated code is needed. The framework turns them into real protobuf
// descriptors at runtime, and the wire format is the standard one, so a
// client generated by protoc can call the example server as well.
package messages

// HelloReq is the request of the unary method.
type HelloReq struct {
	// Name is the name of the guest.
	Name string `pb:"1" validate:"required"`
	// Age is the age of the guest.
	Age int32 `pb:"2"`
}

// HelloResp is the response of the unary method.
type HelloResp struct {
	// Greeting is the greeting of the server.
	Greeting string `pb:"1"`
}

// ChatReq is the request of the streaming method.
type ChatReq struct {
	// Text is the message of the caller.
	Text string `pb:"1"`
}

// ChatResp is the response of the streaming method.
type ChatResp struct {
	// Text is the message that is sent back to the caller.
	Text string `pb:"1"`
}
